initial_repo.stockroom/audit.py:
"""Nightly consistency check over levels, the movement log and open orders."""
from __future__ import annotations

from .inventory import Inventory
from .orders import OrderBook


def replay_on_hand(inventory: Inventory) -> dict[str, int]:
    """On-hand per SKU as implied by the movement log."""
    totals = {s: 0 for s in inventory.skus()}
    for move in inventory.movements:
        if move["kind"] == "receive":
            totals[move["sku"]] += move["qty"]
        elif move["kind"] == "ship":
            totals[move["sku"]] -= move["qty"]
    return totals


def reconcile(inventory: Inventory, book: OrderBook) -> list[str]:
    """Human-readable problems; an empty list means everything agrees."""
    problems = []
    replayed = replay_on_hand(inventory)
    promised: dict[str, int] = {}
    for order in book.open_orders():
        for sku, qty in order.lines.items():
            promised[sku] = promised.get(sku, 0) + qty
    for sku in inventory.skus():
        if replayed[sku] != inventory.on_hand(sku):
            problems.append(f"{sku}: log says {replayed[sku]}, "
                            f"on hand is {inventory.on_hand(sku)}")
        if promised.get(sku, 0) != inventory.reserved(sku):
            problems.append(f"{sku}: orders promise {promised.get(sku, 0)}, "
                            f"reserved is {inventory.reserved(sku)}")
        if inventory.available(sku) < 0:
            problems.append(f"{sku}: available is negative")
    return problems

initial_repo.stockroom/importer.py:
"""Supplier receipts arrive as CSV with a header row: sku,qty[,ref]."""
from __future__ import annotations

import csv
import io

from .inventory import Inventory


class ImportProblem(ValueError):
    def __init__(self, line: int, reason: str) -> None:
        super().__init__(f"line {line}: {reason}")
        self.line = line
        self.reason = reason


def parse_receipts(text: str) -> list[dict]:
    """Validate everything first: a bad row must not half-apply a file."""
    reader = csv.DictReader(io.StringIO(text))
    missing = {"sku", "qty"} - set(reader.fieldnames or [])
    if missing:
        raise ImportProblem(1, f"missing columns: {sorted(missing)}")
    rows = []
    for number, raw in enumerate(reader, start=2):
        sku = (raw.get("sku") or "").strip()
        if not sku:
            raise ImportProblem(number, "empty sku")
        try:
            qty = int(raw["qty"])
        except (TypeError, ValueError):
            raise ImportProblem(number, f"bad qty {raw['qty']!r}") from None
        if qty <= 0:
            raise ImportProblem(number, "qty must be positive")
        rows.append({"sku": sku, "qty": qty, "ref": (raw.get("ref") or "").strip()})
    return rows


def import_receipts(inventory: Inventory, text: str) -> int:
    """Apply a receipts file; returns the units received."""
    rows = parse_receipts(text)
    for row in rows:
        inventory.item(row["sku"])
    for row in rows:
        inventory.receive(row["sku"], row["qty"], ref=row["ref"])
    return sum(r["qty"] for r in rows)

initial_repo.stockroom/inventory.py:
"""Stock levels. One number per SKU: we have one stockroom."""
from __future__ import annotations

from .models import Item


class InsufficientStock(Exception):
    """A request needed more units than are available."""


class UnknownItem(KeyError):
    """The SKU has not been added to the catalog."""


class Inventory:
    def __init__(self) -> None:
        self.items: dict[str, Item] = {}
        self._on_hand: dict[str, int] = {}
        self._reserved: dict[str, int] = {}
        self.movements: list[dict] = []

    # ------------------------------------------------------------ catalog
    def add_item(self, sku: str, name: str, unit_cost_cents: int = 0,
                 reorder_point: int = 0) -> Item:
        if sku in self.items:
            raise ValueError(f"duplicate sku {sku}")
        item = Item(sku, name, unit_cost_cents, reorder_point)
        self.items[sku] = item
        self._on_hand[sku] = 0
        self._reserved[sku] = 0
        return item

    def item(self, sku: str) -> Item:
        try:
            return self.items[sku]
        except KeyError:
            raise UnknownItem(sku) from None

    def skus(self) -> list[str]:
        return sorted(self.items)

    # ------------------------------------------------------------- levels
    def on_hand(self, sku: str) -> int:
        self.item(sku)
        return self._on_hand[sku]

    def reserved(self, sku: str) -> int:
        self.item(sku)
        return self._reserved[sku]

    def available(self, sku: str) -> int:
        return self.on_hand(sku) - self.reserved(sku)

    # ---------------------------------------------------------- mutations
    def receive(self, sku: str, qty: int, ref: str = "") -> None:
        self.item(sku)
        if qty <= 0:
            raise ValueError("qty must be positive")
        self._on_hand[sku] += qty
        self._log("receive", sku, qty, ref)

    def reserve(self, sku: str, qty: int, ref: str = "") -> None:
        if qty <= 0:
            raise ValueError("qty must be positive")
        if qty > self.available(sku):
            raise InsufficientStock(
                f"{sku}: wanted {qty}, have {self.available(sku)}")
        self._reserved[sku] += qty
        self._log("reserve", sku, qty, ref)

    def release(self, sku: str, qty: int, ref: str = "") -> None:
        if qty > self.reserved(sku):
            raise ValueError(f"{sku}: only {self.reserved(sku)} reserved")
        self._reserved[sku] -= qty
        self._log("release", sku, qty, ref)

    def ship(self, sku: str, qty: int, ref: str = "") -> None:
        """Reserved units physically leave the building."""
        if qty > self.reserved(sku):
            raise ValueError(f"{sku}: only {self.reserved(sku)} reserved")
        self._reserved[sku] -= qty
        self._on_hand[sku] -= qty
        self._log("ship", sku, qty, ref)

    def _log(self, kind: str, sku: str, qty: int, ref: str) -> None:
        self.movements.append({"kind": kind, "sku": sku, "qty": qty, "ref": ref})

